class Solution {
    public int numSquares(int n) {
        if (n <= 0) {
            return 0;
        }

        var dp = new int[n + 1];
        // 默认都由 1 组成，当然也可以写成 MAX_VALUE
        for (var i = 1; i <= n; i++) {
            dp[i] = n;
        }

        // f[i] = MIN{ f[i - j * j] + 1 } | j : 1 ~ j * j <= i
        for (var i = 1; i <= n; i++) {
            for (var j = 1; j * j <= i; j++) {
                // 这里不需要判断 dp[i - j * j] != MAX_VALUE, 因为任意数一定能被分成 n 个 1 相加
                dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
            }
        }

        return dp[n];
    }
}

class Solution {
public:
    int numSquares(int n) {
        std::vector<int> memo(n + 1, INT_MAX);
        memo[0] = 0;

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j*j <= i; ++j) {
                memo[i] = std::min(memo[i], 1 + memo[i - j*j]);
            }
        }

        return memo[n];
    }
};

